#include <bits/stdc++.h>
using namespace std;

int main() {
    int N;
    cin >> N;

    vector<vector<int>> a(N, vector<int>(N));
    int zeroRow = -1, zeroCol = -1;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cin >> a[i][j];
            if (a[i][j] == 0) {
                zeroRow = i;
                zeroCol = j;
            }
        }
    }

    int magicSum = 0;
    for (int i = 0; i < N; i++) {
        if (i == zeroRow) continue;

        int sum = 0;
        for (int j = 0; j < N; j++) {
            sum += a[i][j];
        }
        magicSum = sum;
        break;
    }

    int zeroRowSum = 0;
    for (int j = 0; j < N; j++) {
        zeroRowSum += a[zeroRow][j];
    }

    int missingValue = magicSum - zeroRowSum;

    cout << missingValue << '\n';
    cout << zeroRow + 1 << '\n';
    cout << zeroCol + 1 << '\n';

    return 0;
}
